UPDATE "celesnity_app"."tutorial_definitions"
SET
  "metadata" = '{"title":"Create a database and discover source schema","summary":"Create a database, connect a PostgreSQL source, and crawl its schema from a clean workspace.","category":"Getting started","learningOutcomes":["Create a managed database for discovered metadata","Connect a PostgreSQL database source","Test the source connection before saving it","Assign and run a metadata crawler","Browse the discovered source schema"],"estimatedMinutes":15,"stepCount":20}'::jsonb,
  "steps" = '[
    {"id":"database-onboarding-open-create","order":1,"title":"Create a database","instructionalContent":"Start with a database that will contain the metadata discovered from your source. Select Create database.","destinationFeature":"CATALOG_DATABASES","destinationHref":"/catalog/databases","targetControl":{"id":"create-database","accessibleName":"Create database","selector":"[data-tutorial-target=\"create-database\"]"}},
    {"id":"database-onboarding-save-database","order":2,"title":"Save the database","instructionalContent":"Give the database a short name using letters, numbers, or underscores, then create it.","destinationFeature":"CATALOG_DATABASES","destinationHref":"/catalog/databases","requiredAction":{"id":"create-database","accessibleName":"Create database"},"targetControl":{"id":"submit-create-database","accessibleName":"Create database","selector":"[data-tutorial-target=\"submit-create-database\"]"}},
    {"id":"database-onboarding-open-database","order":3,"title":"Open the database","instructionalContent":"Open the database you created to add its first data source.","destinationFeature":"CATALOG_DATABASES","destinationHref":"/catalog/databases","targetControl":{"id":"tutorial-database","accessibleName":"Created database","selector":"[data-tutorial-target=\"tutorial-database\"]"}},
    {"id":"database-onboarding-open-sources","order":4,"title":"Open Sources","instructionalContent":"Sources are the systems this database reads metadata from. Open the Sources tab.","destinationFeature":"CATALOG_DATABASES","destinationHref":"/databases/:database","targetControl":{"id":"database-sources-tab","accessibleName":"Sources","selector":"[data-tutorial-target=\"database-sources-tab\"]"}},
    {"id":"database-onboarding-open-connection","order":5,"title":"Connect a PostgreSQL source","instructionalContent":"Open the connection form for the PostgreSQL database whose schemas and tables you want to discover.","destinationFeature":"CATALOG_DATABASES","destinationHref":"/databases/:database?tab=sources","targetControl":{"id":"new-database-source","accessibleName":"New connection","selector":"[data-tutorial-target=\"new-database-source\"]"}},
    {"id":"database-onboarding-service-name","order":6,"title":"Name the data source","instructionalContent":"Enter a recognizable service name so workspace members can identify this PostgreSQL source.","destinationFeature":"CATALOG_DATABASES","destinationHref":"/databases/:database?tab=sources&create=true","targetControl":{"id":"database-source-service-name","accessibleName":"Service name","selector":"[data-tutorial-target=\"database-source-service-name\"]"}},
    {"id":"database-onboarding-connector","order":7,"title":"Choose PostgreSQL","instructionalContent":"Open Database connector and select PostgreSQL (POSTGRESQL).","destinationFeature":"CATALOG_DATABASES","destinationHref":"/databases/:database?tab=sources&create=true","targetControl":{"id":"database-source-connector","accessibleName":"Database connector","selector":"[data-tutorial-target=\"database-source-connector\"]"}},
    {"id":"database-onboarding-host","order":8,"title":"Enter the host","instructionalContent":"Enter the hostname or IP address that Celesnity can use to reach PostgreSQL.","destinationFeature":"CATALOG_DATABASES","destinationHref":"/databases/:database?tab=sources&create=true","targetControl":{"id":"database-source-host","accessibleName":"Host","selector":"[data-tutorial-target=\"database-source-field-host\"]"}},
    {"id":"database-onboarding-port","order":9,"title":"Enter the port","instructionalContent":"Enter the PostgreSQL port. The default PostgreSQL port is 5432.","destinationFeature":"CATALOG_DATABASES","destinationHref":"/databases/:database?tab=sources&create=true","targetControl":{"id":"database-source-port","accessibleName":"Port","selector":"[data-tutorial-target=\"database-source-field-port\"]"}},
    {"id":"database-onboarding-database-name","order":10,"title":"Enter the database name","instructionalContent":"Enter the PostgreSQL database whose schemas and tables you want to discover.","destinationFeature":"CATALOG_DATABASES","destinationHref":"/databases/:database?tab=sources&create=true","targetControl":{"id":"database-source-database-name","accessibleName":"Database name","selector":"[data-tutorial-target=\"database-source-field-databaseName\"]"}},
    {"id":"database-onboarding-username","order":11,"title":"Enter the username","instructionalContent":"Enter a PostgreSQL user that has permission to read metadata from the database.","destinationFeature":"CATALOG_DATABASES","destinationHref":"/databases/:database?tab=sources&create=true","targetControl":{"id":"database-source-username","accessibleName":"Username","selector":"[data-tutorial-target=\"database-source-field-username\"]"}},
    {"id":"database-onboarding-password","order":12,"title":"Enter the password","instructionalContent":"Enter the password for the PostgreSQL user. The tutorial never displays or stores this value in its progress.","destinationFeature":"CATALOG_DATABASES","destinationHref":"/databases/:database?tab=sources&create=true","targetControl":{"id":"database-source-password","accessibleName":"Password","selector":"[data-tutorial-target=\"database-source-field-password\"]"}},
    {"id":"database-onboarding-test-connection","order":13,"title":"Test the connection","instructionalContent":"Test the PostgreSQL details before saving. Continue after the workspace completes the connection test.","destinationFeature":"CATALOG_DATABASES","destinationHref":"/databases/:database?tab=sources&create=true","requiredAction":{"id":"test-database-connection","accessibleName":"Test connection"},"targetControl":{"id":"test-database-source","accessibleName":"Test connection","selector":"[data-tutorial-target=\"test-database-source\"]"}},
    {"id":"database-onboarding-save-connection","order":14,"title":"Save the data source","instructionalContent":"Save the tested PostgreSQL service so it can be assigned a metadata crawler.","destinationFeature":"CATALOG_DATABASES","destinationHref":"/databases/:database?tab=sources&create=true","requiredAction":{"id":"create-database-source","accessibleName":"Save service"},"targetControl":{"id":"save-database-source","accessibleName":"Save service","selector":"[data-tutorial-target=\"save-database-source\"]"}},
    {"id":"database-onboarding-open-source","order":15,"title":"Open the data source","instructionalContent":"Open the PostgreSQL source you just connected to configure schema discovery.","destinationFeature":"CATALOG_DATABASES","destinationHref":"/databases/:database?tab=sources","targetControl":{"id":"tutorial-database-source","accessibleName":"Created data source","selector":"[data-tutorial-target=\"tutorial-database-source\"]"}},
    {"id":"database-onboarding-open-scan","order":16,"title":"Open Metadata scan","instructionalContent":"The Metadata scan tab contains the crawler that discovers schemas, tables, and columns.","destinationFeature":"CRAWLER","destinationHref":"/databases/:database/sources/:sourceId","targetControl":{"id":"source-scan-tab","accessibleName":"Metadata scan","selector":"[data-tutorial-target=\"source-scan-tab\"]"}},
    {"id":"database-onboarding-open-crawler-dialog","order":17,"title":"Assign a crawler","instructionalContent":"Assign a metadata crawler to this source and choose when it should refresh the schema.","destinationFeature":"CRAWLER","destinationHref":"/databases/:database/sources/:sourceId?tab=scan","targetControl":{"id":"assign-metadata-crawler","accessibleName":"Assign crawler","selector":"[data-tutorial-target=\"assign-metadata-crawler\"]"}},
    {"id":"database-onboarding-save-crawler","order":18,"title":"Save crawler assignment","instructionalContent":"Keep or adjust the schedule, then save the crawler assignment.","destinationFeature":"CRAWLER","destinationHref":"/databases/:database/sources/:sourceId?tab=scan&assignCrawler=true","requiredAction":{"id":"assign-metadata-crawler","accessibleName":"Save assignment"},"targetControl":{"id":"save-metadata-crawler","accessibleName":"Save assignment","selector":"[data-tutorial-target=\"save-metadata-crawler\"]"}},
    {"id":"database-onboarding-run-crawler","order":19,"title":"Run the crawler","instructionalContent":"Run the crawler now so the source schema is discovered without waiting for the schedule.","destinationFeature":"CRAWLER","destinationHref":"/databases/:database/sources/:sourceId?tab=scan","requiredAction":{"id":"run-metadata-crawler","accessibleName":"Scan now"},"targetControl":{"id":"run-metadata-crawler","accessibleName":"Scan now","selector":"[data-tutorial-target=\"run-metadata-crawler\"]"}},
    {"id":"database-onboarding-browse-schema","order":20,"title":"Browse discovered schema","instructionalContent":"Open Tables to review the schemas, tables, and columns discovered by the crawler.","destinationFeature":"SOURCE_SCHEMA","destinationHref":"/databases/:database/sources/:sourceId","targetControl":{"id":"source-tables-tab","accessibleName":"Tables","selector":"[data-tutorial-target=\"source-tables-tab\"]"}}
  ]'::jsonb,
  "prerequisites" = '[{"id":"postgresql-access","description":"Access to a PostgreSQL database and its connection details: host, port, database name, username, and password.","informational":true}]'::jsonb,
  "revision" = "revision" + 1,
  "updated_at" = CURRENT_TIMESTAMP
WHERE "id" = 'tutorial-connections-basics';

-- The expanded revision inserts eight steps inside the previous ordered
-- prefix. Restart active checkpoints so saved progress cannot skip the new
-- PostgreSQL fields. Completion history remains available separately.
UPDATE "celesnity_app"."tutorial_progress"
SET
  "status" = 'NOT_STARTED',
  "current_step_id" = 'database-onboarding-open-create',
  "completed_step_ids" = ARRAY[]::TEXT[],
  "context_selections" = '[]'::jsonb,
  "updated_at" = CURRENT_TIMESTAMP
WHERE "tutorial_id" = 'tutorial-connections-basics';
